    case 26:
      ACCEPT_TOKEN(anon_sym_true);
      END_STATE();
    case 27:
      ACCEPT_TOKEN(anon_sym_type);
      END_STATE();
    case 28:
      if (lookahead == 'd') ADVANCE(32);
      END_STATE();
    case 29:
      ACCEPT_TOKEN(anon_sym_false);
      END_STATE();
    case 30:
      if (lookahead == 'a') ADVANCE(33);
      END_STATE();
    case 31:
